const A=window.AtomApp;const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let msg='',loaded=false,store={},saving=false;function notice(){return '<div class="status" role="status">'+esc(msg)+(loaded?'':' <button id="retry-load">重试读取</button>')+'</div>'}function wire(){if($('retry-load'))$('retry-load').onclick=()=>readStore();}async function readStore(){if(A)A.deferReady();try{store=A?await A.load(DEFAULT):JSON.parse(JSON.stringify(DEFAULT));if(!store||typeof store!=='object')throw Error();loaded=true;msg='';afterLoad();}catch(e){loaded=false;msg='读取失败，未覆盖已有记录';render()}finally{if(A)A.ready()}}async function saveStore(next){if(!loaded||saving)return false;saving=true;msg='正在保存…';render();try{if(!A)throw Error();await A.save(next);store=next;msg='已保存';return true}catch(e){msg='保存失败，请重试';return false}finally{saving=false;render()}}function setBack(fn){if(A)AtomApp.navigation.setBackHandler(fn)}function home(){if(A)A.home()}function afterLoad(){render()}if(A)A.onSuspend(()=>{document.getAnimations().forEach(x=>x.cancel());suspend()});function suspend(){}
const DEFAULT={};const W=120,H=58,grid=new Uint8Array(W*H),colors=['#101a29','#d8bd81','#679ec7','#f49b4c','#7da984','#b99c88'];let material=1,lane=2,paused=false,frame=0,alive=true,tick=0;function suspend(){alive=false;cancelAnimationFrame(frame)}function reset(){grid.fill(0);for(let x=0;x<W;x++)grid[(H-1)*W+x]=5;for(let x=40;x<80;x++)grid[(H-12)*W+x]=5}
function drop(){let cx=12+lane*24;for(let x=cx-3;x<=cx+3;x++)for(let y=1;y<5;y++)if(x>=0&&x<W&&grid[y*W+x]===0)grid[y*W+x]=material}
function step(){tick++;for(let y=H-2;y>=0;y--){let reverse=tick%2;for(let k=0;k<W;k++){let x=reverse?W-1-k:k,i=y*W+x,v=grid[i];if(v===1||v===2){let d=i+W,side=Math.random()<.5?-1:1;if(grid[d]===0||(v===1&&grid[d]===2)){grid[i]=grid[d];grid[d]=v}else if(x+side>=0&&x+side<W&&grid[d+side]===0){grid[d+side]=v;grid[i]=0}else if(v===2&&x+side>=0&&x+side<W&&grid[i+side]===0){grid[i+side]=2;grid[i]=0}}else if(v===3){if(Math.random()<.07)grid[i]=0;for(let d of [-1,1,-W,W]){let j=i+d;if(j<0||j>=grid.length)continue;if(grid[j]===2){grid[j]=0;grid[i]=0}else if(grid[j]===4&&Math.random()<.2)grid[j]=3}}else if(v===4&&Math.random()<.03){for(let d of [-1,1,-W]){let j=i+d;if(j>=0&&j<grid.length&&grid[j]===2)grid[j]=4}}}}}
function draw(){let c=$('sand');if(!c)return;let g=c.getContext('2d'),im=g.createImageData(W,H);for(let i=0;i<grid.length;i++){let hex=colors[grid[i]],v=parseInt(hex.slice(1),16);im.data[i*4]=v>>16;im.data[i*4+1]=v>>8&255;im.data[i*4+2]=v&255;im.data[i*4+3]=255}g.putImageData(im,0,0);g.fillStyle='#f3e7cd';g.fillRect(12+lane*24-1,0,3,1)}
function render(){$('screen').innerHTML='<canvas id="sand" width="120" height="58" aria-label="元素沙盘"></canvas><div class="sandbox-tools"><select id="material" aria-label="投放材料">'+['沙','水','火','植物','石墙'].map((n,i)=>'<option value="'+(i+1)+'" '+(material===i+1?'selected':'')+'>'+n+'</option>').join('')+'</select><button id="left">‹</button><button id="drop">投放 '+(lane+1)+'</button><button id="right">›</button><button id="pause">'+(paused?'继续':'暂停')+'</button><button id="reset">清空</button></div><div class="foot">水灭火，火烧植物，植物遇水生长 · 5 个投放口</div>';$('material').onchange=e=>material=Number(e.target.value);$('left').onclick=()=>{lane=(lane+4)%5;render()};$('right').onclick=()=>{lane=(lane+1)%5;render()};$('drop').onclick=drop;$('pause').onclick=()=>{paused=!paused;render()};$('reset').onclick=()=>{reset();draw()};draw()}
function loop(){if(!alive)return;if(!paused)step();draw();frame=requestAnimationFrame(loop)}setBack(home);reset();render();frame=requestAnimationFrame(loop);
